export type ThemeName = "light" | "dark" | "system"

function validateThemeNameInto(value: any, path: string): boolean {
  return oneOf(value, path, ["light","dark","system"])
}

/** The first problem with `value` as a theme-name, or null. */
export const validateThemeName = (value: unknown) => run(validateThemeNameInto, value)

export type UiEntry = { "key": string, "value": string }

function validateUiEntryInto(value: any, path: string): boolean {
  return map(value, path, ["key","value"]) && (value["key"] === undefined ? fail(`${path}.key`, 'present') : nested(value["key"], `${path}.key`, (value, path) => typeof value === 'string' || fail(path, 'text'))) && (value["value"] === undefined ? fail(`${path}.value`, 'present') : nested(value["value"], `${path}.value`, (value, path) => typeof value === 'string' || fail(path, 'text')))
}

/** The first problem with `value` as a ui-entry, or null. */
export const validateUiEntry = (value: unknown) => run(validateUiEntryInto, value)

export type SettingsState = { "settings": Settings, "notice"?: string, "noticeCode"?: string }

function validateSettingsStateInto(value: any, path: string): boolean {
  return map(value, path, ["settings","notice","noticeCode"]) && (value["settings"] === undefined ? fail(`${path}.settings`, 'present') : nested(value["settings"], `${path}.settings`, (value, path) => validateSettingsInto(value, path))) && (value["notice"] === undefined || nested(value["notice"], `${path}.notice`, (value, path) => typeof value === 'string' || fail(path, 'text'))) && (value["noticeCode"] === undefined || nested(value["noticeCode"], `${path}.noticeCode`, (value, path) => typeof value === 'string' || fail(path, 'text')))
}

/** The first problem with `value` as a settings-state, or null. */
export const validateSettingsState = (value: unknown) => run(validateSettingsStateInto, value)

export type SettingsPatch = { "language"?: string, "theme"?: ThemeName, "ui"?: (UiEntry)[], "remove"?: (string)[] }

function validateSettingsPatchInto(value: any, path: string): boolean {
  return map(value, path, ["language","theme","ui","remove"]) && (value["language"] === undefined || nested(value["language"], `${path}.language`, (value, path) => typeof value === 'string' || fail(path, 'text'))) && (value["theme"] === undefined || nested(value["theme"], `${path}.theme`, (value, path) => validateThemeNameInto(value, path))) && (value["ui"] === undefined || nested(value["ui"], `${path}.ui`, (value, path) => list(value, path, (value, path) => validateUiEntryInto(value, path)))) && (value["remove"] === undefined || nested(value["remove"], `${path}.remove`, (value, path) => list(value, path, (value, path) => typeof value === 'string' || fail(path, 'text'))))
}

/** The first problem with `value` as a settings-patch, or null. */
export const validateSettingsPatch = (value: unknown) => run(validateSettingsPatchInto, value)

export type FileSave = { "name": string, "text": string }

function validateFileSaveInto(value: any, path: string): boolean {
  return map(value, path, ["name","text"]) && (value["name"] === undefined ? fail(`${path}.name`, 'present') : nested(value["name"], `${path}.name`, (value, path) => typeof value === 'string' || fail(path, 'text'))) && (value["text"] === undefined ? fail(`${path}.text`, 'present') : nested(value["text"], `${path}.text`, (value, path) => typeof value === 'string' || fail(path, 'text')))
}

/** The first problem with `value` as a file-save, or null. */
export const validateFileSave = (value: unknown) => run(validateFileSaveInto, value)

export type FileSaved = { "path"?: string }

function validateFileSavedInto(value: any, path: string): boolean {
  return map(value, path, ["path"]) && (value["path"] === undefined || nested(value["path"], `${path}.path`, (value, path) => typeof value === 'string' || fail(path, 'text')))
}

/** The first problem with `value` as a file-saved, or null. */
export const validateFileSaved = (value: unknown) => run(validateFileSavedInto, value)

export type FileOpened = { "path"?: string, "text"?: string }

function validateFileOpenedInto(value: any, path: string): boolean {
  return map(value, path, ["path","text"]) && (value["path"] === undefined || nested(value["path"], `${path}.path`, (value, path) => typeof value === 'string' || fail(path, 'text'))) && (value["text"] === undefined || nested(value["text"], `${path}.text`, (value, path) => typeof value === 'string' || fail(path, 'text')))
}

/** The first problem with `value` as a file-opened, or null. */
export const validateFileOpened = (value: unknown) => run(validateFileOpenedInto, value)

export type SerialPorts = { "ports": (SerialPort)[] }

function validateSerialPortsInto(value: any, path: string): boolean {
  return map(value, path, ["ports"]) && (value["ports"] === undefined ? fail(`${path}.ports`, 'present') : nested(value["ports"], `${path}.ports`, (value, path) => list(value, path, (value, path) => validateSerialPortInto(value, path))))
}

/** The first problem with `value` as a serial-ports, or null. */
export const validateSerialPorts = (value: unknown) => run(validateSerialPortsInto, value)

export type SerialPort = { "path": string, "description"?: string }

function validateSerialPortInto(value: any, path: string): boolean {
  return map(value, path, ["path","description"]) && (value["path"] === undefined ? fail(`${path}.path`, 'present') : nested(value["path"], `${path}.path`, (value, path) => typeof value === 'string' || fail(path, 'text'))) && (value["description"] === undefined || nested(value["description"], `${path}.description`, (value, path) => typeof value === 'string' || fail(path, 'text')))
}

/** The first problem with `value` as a serial-port, or null. */
export const validateSerialPort = (value: unknown) => run(validateSerialPortInto, value)

/** The services, for a typed Communicator. */
export interface Services {
  "vehicle.connect": { kind: 'method', request: ConnectRequest, response: Connection }
  "vehicle.disconnect": { kind: 'method', request: null, response: Connection }
  "vehicle.connection": { kind: 'subscription', params: null, value: Connection }
  "params.list": { kind: 'method', request: ParamListRequest, response: ParamList }
  "params.cancel": { kind: 'method', request: null, response: null }
  "params.progress": { kind: 'event', payload: ParamsProgress }
  "params.write": { kind: 'method', request: ParamWrite, response: ParamWriteResult }
  "logs.vehicle.list": { kind: 'method', request: null, response: VehicleLogs }
  "logs.download": { kind: 'method', request: LogsDownload, response: LogsDownloaded }
  "logs.cancel": { kind: 'method', request: null, response: null }
  "logs.erase": { kind: 'method', request: null, response: LogsErased }
  "logs.progress": { kind: 'event', payload: LogsProgress }
  "logs.local.list": { kind: 'method', request: null, response: LocalLogs }
  "logs.local.read": { kind: 'method', request: LogsLocalRead, response: LocalLogSummary }
  "logs.local.modes": { kind: 'method', request: LogsLocalRead, response: LocalLogModes }
  "logs.local.series": { kind: 'method', request: LogsLocalSeriesAsk, response: LogsLocalSeries }
  "logs.local.cancel": { kind: 'method', request: null, response: null }
  "logs.local.progress": { kind: 'event', payload: LogsLocalProgress }
  "vehicle.reboot": { kind: 'method', request: null, response: RebootResult }
  "telemetry.stream": { kind: 'subscription', params: TelemetryParams, value: Telemetry }
  "vehicle.messages": { kind: 'subscription', params: MessagesParams, value: VehicleMessage }
  "files.save": { kind: 'method', request: FileSave, response: FileSaved }
  "files.open": { kind: 'method', request: null, response: FileOpened }
  "serial.ports": { kind: 'method', request: null, response: SerialPorts }
  "settings.get": { kind: 'method', request: null, response: SettingsState }
  "settings.set": { kind: 'method', request: SettingsPatch, response: SettingsState }
  "settings.changed": { kind: 'event', payload: SettingsState }
  "params.changed": { kind: 'event', payload: Param }
}

const services: Record<string, Partial<Record<string, Check>>> = {
  "vehicle.connect": {
    request: (value: any, path: string) => validateConnectRequestInto(value, path),
    response: (value: any, path: string) => validateConnectionInto(value, path),
  },
  "vehicle.disconnect": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateConnectionInto(value, path),
  },
  "vehicle.connection": {
    params: (value: any, path: string) => value === null || fail(path, 'null'),
    value: (value: any, path: string) => validateConnectionInto(value, path),
  },
  "params.list": {
    request: (value: any, path: string) => validateParamListRequestInto(value, path),
    response: (value: any, path: string) => validateParamListInto(value, path),
  },
  "params.cancel": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => value === null || fail(path, 'null'),
  },
  "params.progress": {
    payload: (value: any, path: string) => validateParamsProgressInto(value, path),
  },
  "params.write": {
    request: (value: any, path: string) => validateParamWriteInto(value, path),
    response: (value: any, path: string) => validateParamWriteResultInto(value, path),
  },
  "logs.vehicle.list": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateVehicleLogsInto(value, path),
  },
  "logs.download": {
    request: (value: any, path: string) => validateLogsDownloadInto(value, path),
    response: (value: any, path: string) => validateLogsDownloadedInto(value, path),
  },
  "logs.cancel": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => value === null || fail(path, 'null'),
  },
  "logs.erase": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateLogsErasedInto(value, path),
  },
  "logs.progress": {
    payload: (value: any, path: string) => validateLogsProgressInto(value, path),
  },
  "logs.local.list": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateLocalLogsInto(value, path),
  },
  "logs.local.read": {
    request: (value: any, path: string) => validateLogsLocalReadInto(value, path),
    response: (value: any, path: string) => validateLocalLogSummaryInto(value, path),
  },
  "logs.local.modes": {
    request: (value: any, path: string) => validateLogsLocalReadInto(value, path),
    response: (value: any, path: string) => validateLocalLogModesInto(value, path),
  },
  "logs.local.series": {
    request: (value: any, path: string) => validateLogsLocalSeriesAskInto(value, path),
    response: (value: any, path: string) => validateLogsLocalSeriesInto(value, path),
  },
  "logs.local.cancel": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => value === null || fail(path, 'null'),
  },
  "logs.local.progress": {
    payload: (value: any, path: string) => validateLogsLocalProgressInto(value, path),
  },
  "vehicle.reboot": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateRebootResultInto(value, path),
  },
  "telemetry.stream": {
    params: (value: any, path: string) => validateTelemetryParamsInto(value, path),
    value: (value: any, path: string) => validateTelemetryInto(value, path),
  },
  "vehicle.messages": {
    params: (value: any, path: string) => validateMessagesParamsInto(value, path),
    value: (value: any, path: string) => validateVehicleMessageInto(value, path),
  },
  "files.save": {
    request: (value: any, path: string) => validateFileSaveInto(value, path),
    response: (value: any, path: string) => validateFileSavedInto(value, path),
  },
  "files.open": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateFileOpenedInto(value, path),
  },
  "serial.ports": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateSerialPortsInto(value, path),
  },
  "settings.get": {
    request: (value: any, path: string) => value === null || fail(path, 'null'),
    response: (value: any, path: string) => validateSettingsStateInto(value, path),
  },
  "settings.set": {
    request: (value: any, path: string) => validateSettingsPatchInto(value, path),
    response: (value: any, path: string) => validateSettingsStateInto(value, path),
  },
  "settings.changed": {
    payload: (value: any, path: string) => validateSettingsStateInto(value, path),
  },
  "params.changed": {
    payload: (value: any, path: string) => validateParamInto(value, path),
  },
}

/** Checks an incoming payload against the contract (the Communicator's `validate` option). */
export const validate = (name: string, part: string, value: unknown): string | null => {
  const check = services[name]?.[part]

  // An absent payload is null on the wire.
  return check ? run(check, value ?? null) : null
}
